            4'd10: row=32'h066aa990;
            4'd11: row=32'h056aa950;
            4'd12: row=32'h005aa500;
            4'd13: row=32'h00514500;
            4'd14: row=32'h01514540;
            4'd15: row=32'h00000000;
            default: row=0;
        endcase
    end
    always @(posedge clk) begin
        case(color_index)
            2'd0: pixel<=8'd0;
